import contextlib
import io
import json
import unittest
from typing import Any
from unittest import mock

from build.beads.scripts import guard_audit as ga

_HEADER = (
    "[AI-generated by planter] Package cutover summary for patchset {ps}\n\n"
)


def _block(guard: str, compared: bool = True) -> str:
    contents = (
        "- Differences: package contents 0, build commands 0.\n"
        if compared
        else "- Package contents: not compared (no phase-1 record).\n"
    )
    return (
        "**Package cutover:** `snapshot` (GN `//a:pkg` -> Bazel `//a:pkg`), "
        "phase `final`.\n\n" + contents + f"- Guard: {guard}\n"
    )


def _comment(ps: int, *blocks: str) -> dict[str, Any]:
    return {
        "message": _HEADER.format(ps=ps) + "\n".join(blocks),
        "patch_set": ps,
        "updated": f"2026-11-1{ps} 00:00:00.000",
    }


def _gate(rec: dict[str, Any], ps: int = 1) -> dict[str, Any]:
    return {
        "message": "Gate record.\n\n```planter-gate-record\n"
        + json.dumps(rec)
        + "\n```\n\nPlanter gate record.",
        "patch_set": ps,
        "updated": f"2026-11-1{ps} 01:00:00.000",
    }


_DIFF = {
    "category": "cutover_diff_cmd_flags",
    "key": "snapshot:bin/snapshot rustc",
    "stage": 0,
    "fingerprint": "f1",
}
_GUARD = {
    "category": "cutover_diff_guard",
    "key": "snapshot:meta.far",
    "stage": 1,
    "fingerprint": "g1",
}
_UNVERIFIED = {
    "category": "cutover_info_not_compared",
    "package": "//src/snap:pkg",
    "fingerprint": "u1",
}


def _decision(
    item: dict[str, Any], verdict: str, fp: str = ""
) -> dict[str, Any]:
    key = item.get("key", item.get("package"))
    return {
        "id": f"{item['category']}:{key}",
        "fingerprint": fp or item["fingerprint"],
        "stage": item.get("stage", 0),
        "verdict": verdict,
        "by": "a@google.com",
        "patchset": 1,
    }


_CHANGE = {
    "_number": 42,
    "subject": "[bazel_migration] snapshot",
    "status": "MERGED",
    "owner": {"email": "a@google.com"},
    "submitted": "2026-11-14 10:00:00.000",
    "revisions": {
        "r1": {"_number": 1, "kind": "REWORK"},
        "r2": {"_number": 2, "kind": "REWORK"},
        "r3": {"_number": 3, "kind": "NO_CODE_CHANGE"},
    },
}


class ClassifyTest(unittest.TestCase):
    def test_statuses(self) -> None:
        cases = (
            (_block("passed: the Bazel package is unchanged"), "ok"),
            (
                _block("FAILED: 1 difference(s) not reported in phase 1"),
                "failed",
            ),
            (_block("record predates recompare (v1); FAILED (x)"), "failed"),
            (
                _block("unverified (no phase-1 record)", compared=False),
                "unverified",
            ),
            (
                _block("not recompared (the Bazel package did not build)"),
                "unverified",
            ),
            (
                _block(
                    "record predates recompare (v1); skipped (rebased since "
                    "phase 1; see cutover_info_guard_rebased)"
                ),
                "unverified",
            ),
            (_block("phase-1 record not written (builds skipped)"), "ok"),
        )
        for text, status in cases:
            with self.subTest(text=text):
                summary = ga._classify(_HEADER.format(ps=1) + text)
                assert summary is not None
                self.assertEqual(summary["status"], status)

    def test_old_not_compared_format(self) -> None:
        text = _HEADER.format(ps=1) + (
            "**Package cutover:** `x` (GN `//a:x` -> Bazel `//a:x`), phase `final`.\n"
            "- Differences: package contents not compared (no phase-1 record), "
            "build commands not compared (no phase-1 record).\n"
            "- Guard: unverified (no phase-1 record)\n"
        )
        summary = ga._classify(text)
        assert summary is not None
        self.assertEqual(summary["status"], "unverified")

    def test_partly_compared_is_partly_unverified(self) -> None:
        text = _HEADER.format(ps=1) + "\n".join(
            (_block("passed: x"), _block("unverified (y)", compared=False))
        )
        summary = ga._classify(text)
        assert summary is not None
        self.assertEqual(
            (summary["status"], summary["packages"], summary["not_compared"]),
            ("partly_unverified", 2, 1),
        )

    def test_not_a_summary(self) -> None:
        self.assertIsNone(ga._classify("LGTM"))
        self.assertIsNone(ga._classify("- Guard: FAILED but no summary"))


class AuditChangeTest(unittest.TestCase):
    def test_latest_summary_and_history(self) -> None:
        comments = {
            "/PATCHSET_LEVEL": [
                _comment(2, _block("FAILED: 1 difference(s)")),
                _comment(1, _block("unverified (z)", compared=False)),
                {"message": "unrelated", "patch_set": 2, "updated": ""},
            ]
        }
        row = ga._audit_change(_CHANGE, comments)
        assert row is not None
        self.assertEqual(row["last_summary_ps"], 2)
        self.assertEqual(row["last_status"], "failed")
        self.assertTrue(row["ever_failed"])
        self.assertTrue(row["ever_unverified"])
        self.assertSequenceEqual(
            row["history"], ("ps1:unverified", "ps2:failed")
        )
        self.assertSequenceEqual(
            row["later_patchset_kinds"], ("NO_CODE_CHANGE",)
        )
        self.assertEqual(row["latest_ps"], 3)
        self.assertEqual(row["cutover_review"], "unknown")

    def review(self, *gates: dict[str, Any]) -> tuple[str, str, int]:
        comments = {
            "/PATCHSET_LEVEL": [_comment(1, _block("passed: x")), *gates]
        }
        row = ga._audit_change(_CHANGE, comments)
        assert row is not None
        return (
            row["cutover_review"],
            row["cutover_decided"],
            row["gate_record_ps"],
        )

    def test_v2_cutover_decisions(self) -> None:
        items = {
            "version": 2,
            "patchset": 1,
            "cutover_diffs": [_DIFF, _GUARD],
            "cutover_unverified": [_UNVERIFIED],
        }
        self.assertEqual(self.review(_gate(items)), ("pending", "0/3", 1))
        decisions = [
            _decision(_DIFF, "approved"),
            _decision(_GUARD, "benign"),
            _decision(_UNVERIFIED, "approved"),
        ]
        decided = items | {"cutover_decisions": decisions}
        self.assertEqual(
            self.review(_gate(items), _gate(decided | {"patchset": 2}, ps=2)),
            ("approved", "3/3", 2),
        )
        # A stage-1 item needs a real/benign verdict, and a decision covers
        # only the content (fingerprint) it was made on.
        for bad in (
            _decision(_GUARD, "approved"),
            _decision(_GUARD, "benign", fp="g0"),
        ):
            with self.subTest(bad=bad):
                rec = decided | {
                    "cutover_decisions": decisions[:1] + [bad] + decisions[2:]
                }
                self.assertEqual(self.review(_gate(rec)), ("pending", "2/3", 1))
        # The v1 acknowledgment means nothing in a v2 record.
        acked = items | {"acknowledgment": {"by": "a", "patchset": 1}}
        self.assertEqual(self.review(_gate(acked)), ("pending", "0/3", 1))

    def test_v1_acknowledgment_and_no_items(self) -> None:
        v1 = {"version": 1, "patchset": 2, "cutover_diffs": [_DIFF]}
        self.assertEqual(self.review(_gate(v1, ps=2)), ("pending", "0/1", 2))
        stale = v1 | {"acknowledgment": {"by": "a", "patchset": 1}}
        self.assertEqual(self.review(_gate(stale, ps=2)), ("pending", "0/1", 2))
        acked = v1 | {"acknowledgment": {"by": "a", "patchset": 2}}
        self.assertEqual(
            self.review(_gate(acked, ps=2)), ("approved", "1/1", 2)
        )
        self.assertEqual(
            self.review(_gate({"version": 2, "patchset": 1})),
            ("none", "0/0", 1),
        )
        omitted = {"version": 2, "patchset": 1, "omitted_cutover_diffs": 2}
        self.assertEqual(self.review(_gate(omitted)), ("unknown", "0/2", 1))

    def test_no_summary(self) -> None:
        self.assertIsNone(ga._audit_change(_CHANGE, {"/PATCHSET_LEVEL": []}))


class MainTest(unittest.TestCase):
    @mock.patch.object(ga, "_get", autospec=True)
    def test_json_and_flagged(self, mock_get: mock.MagicMock) -> None:
        comments = {
            "/PATCHSET_LEVEL": [
                _comment(1, _block("unverified", compared=False))
            ]
        }
        ok_change = _CHANGE | {"_number": 43}
        ok_comments = {"/PATCHSET_LEVEL": [_comment(1, _block("passed: x"))]}

        def fake_get(path: str, attempts: int = 5) -> Any:
            if path.startswith("/changes/?q="):
                self.assertIn("status%3Aopen", path)
                self.assertIn("after%3A2026-11-01", path)
                return [_CHANGE, ok_change]
            return comments if "/42/" in path else ok_comments

        mock_get.side_effect = fake_get
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            ga.main(
                (
                    "--status",
                    "open",
                    "--after",
                    "2026-11-01",
                    "--json",
                    "--only-flagged",
                )
            )
        data = json.loads(out.getvalue())
        self.assertEqual(data["scanned"], 2)
        self.assertSequenceEqual([r["change"] for r in data["rows"]], (42,))
        self.assertEqual(
            data["counts"],
            {"failed": 0, "unverified": 1, "partly_unverified": 0, "ok": 0},
        )


if __name__ == "__main__":
    unittest.main()
